from pathlib import Path
import base64, hashlib, subprocess, sys, zlib

root = Path(sys.argv[1]).resolve()
payload = "";
patch = zlib.decompress(base64.b64decode(payload))
expected = "34a9ee686eceb023a7c00f2f4e2752774d9d26a4245137743779e5d8d41e3872"
actual = hashlib.sha256(patch).hexdigest()
if actual != expected:
    raise RuntimeError(f"alpha41 patch checksum mismatch: {actual} != {expected}")
subprocess.run(["git", "-C", str(root), "apply", "--whitespace=nowarn", "-"], input=patch, check=True)
print("PKVault V8 alpha41 persistent quest history + live dailies + green completions + collapsible bank + Insurgence item names applied")
